            "The corticosteroid reduces swelling around the compressed nerve root, breaking the inflammatory cycle that sustains sciatica pain. Many patients experience significant relief within days to two weeks. For those with disc herniation, this window of reduced pain allows the disc to heal and decompression to occur naturally, often making surgery unnecessary.",
            "At Jain Pain Clinic in Gurugram, Dr. Ashu Kumar Jain performs transforaminal epidural steroid injections under live fluoroscopic guidance, targeting the precise nerve root level and side identified on the patient's MRI - not a generalised injection, but a placement matched to the specific structural finding."
