    "seoTitle": "Chronic Pain and Sleep: Why You Can't Rest – Jain Pain Clinic",
    "description": "Pain disrupts sleep. Poor sleep intensifies pain. Understanding this vicious cycle - and how to break it - is one of the most important steps in chronic pain management.",
    "keywords": "chronic pain and sleep, pain insomnia, sleep deprivation pain, chronic pain management, pain affects sleep, Jain Pain Clinic Gurugram, Dr. Ashu Kumar Jain",
