    "readTime": "8 min read",
    "excerpt": "Pain disrupts sleep. Poor sleep intensifies pain. Here is the science behind this vicious cycle and how to escape it.",
    "heroSubtitle": "Almost every chronic pain patient says the same thing: \"I can't sleep because of the pain.\" What most don't realise is that the reverse is equally true - the poor sleep is making the pain worse. Understanding this cycle is the first step to breaking it.",
    "author": "Dr Ashu Kumar Jain",
    "authorImage": "/assets/logo.png",
    "publishedAt": "2026-05-05",
    "publishedLabel": "May 5, 2026",
    "cardImage": "/assets/blog/sleep-pain-hero.jpg",
